{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const c of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(c)) fail(`error: line ${n}: invalid candidate name ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is declared twice`)
      seen.add(c)
    }
    names = t.slice(1)
  } else if (word === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const c of t.slice(2)) {
      if (!names.includes(c)) fail(`error: line ${n}: unknown candidate ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is repeated`)
      seen.add(c)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
})
if (names === null) fail('error: no candidates')

const alive = new Set(names)
const history = []
const out = []
let winner = null
for (;;) {
  const counts = new Map([...alive].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => alive.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let exhausted = 0n
  for (const b of ballots) exhausted += b.count
  exhausted -= active
  history.push(counts)
  const order = [...alive].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    if (d !== 0n) return d > 0n ? 1 : -1
    return a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${history.length}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`)
  if (active === 0n) break
  const top = order.find((c) => counts.get(c) * 2n > active)
  if (top !== undefined) {
    winner = top
    break
  }
  let min = counts.get(order[order.length - 1])
  let tied = order.filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const m = tied.reduce((a, c) => (history[r].get(c) < a ? history[r].get(c) : a), history[r].get(tied[0]))
    tied = tied.filter((c) => history[r].get(c) === m)
  }
  const elim = tied.reduce((a, c) => (c > a ? c : a))
  alive.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
